// Generated by CoffeeScript 1.9.3
document.addEventListener("DOMContentLoaded", () => {
  const message = "Поздравляю, если Вы видите это, Вы по-прежнему приглашены на девичник Анастасии! Соизвольте явиться, как и было оговорено, 20 декабря (воскресенье) текущего года в 18-00 в Литературное кафе COOK&GEEK на Петроградской Стороне, по адресу Большой проспект, 81 (кому требуются дополнительные вводные — высылайте голубиную почту). Проходить на территорию сего милейшего мероприятия без благостного настроя воспрещается.";

  document.body.style.background = "#293134";
  document.body.style.color = "#293134";

  const innerContainer = document.querySelector(".inner");
  if (!innerContainer) return;

  const fragment = document.createDocumentFragment();
  for (let i = 0; i < message.length; i += 1) {
    const ch = message[i] === " " ? "\u00A0" : message[i];
    const el = document.createElement("div");
    el.id = `char${i}`;
    el.className = "inline char";
    el.innerHTML = ch;
    fragment.appendChild(el);
  }
  innerContainer.appendChild(fragment);

  const chars = Array.from(innerContainer.querySelectorAll(".char"));
  const states = chars.map((el) => {
    const rect = el.getBoundingClientRect();
    return {
      el,
      left: rect.left + window.scrollX,
      top: rect.top + window.scrollY,
      width: el.offsetWidth,
      height: el.offsetHeight,
    };
  });

  const maxWidth = Math.max(...states.map((s) => s.width));
  const maxHeight = Math.max(...states.map((s) => s.height));

  // Switch to absolute positioning at recorded locations
  states.forEach((s) => {
    s.el.classList.remove("inline");
    s.el.classList.add("absolute");
    s.el.style.left = `${s.left}px`;
    s.el.style.top = `${s.top}px`;
    s.el.style.transform = `translate3d(0, 0, 0)`;
  });

  function animateShuffle() {
    const w = window.innerWidth;
    const h = window.innerHeight;
    states.forEach((s) => {
      const targetLeft = Math.random() * (w - maxWidth);
      const targetTop = Math.random() * (h - maxHeight);
      const dx = targetLeft - s.left;
      const dy = targetTop - s.top;
      s.el.style.transform = `translate3d(${dx}px, ${dy}px, 0)`;
    });
  }

  function animateRestore() {
    states.forEach((s) => {
      s.el.style.transform = `translate3d(0, 0, 0)`;
    });
  }

  let action = animateRestore;
  animateShuffle();
  document.body.style.color = "#e0e2e4";

  function clickTap() {
    action();
    action = action === animateShuffle ? animateRestore : animateShuffle;
  }

  document.body.addEventListener("click", clickTap);
  document.body.addEventListener("touchstart", clickTap, { passive: true });
});
